    add("recover", "復帰", baseCells[0] > 0 && baseCells[1] > 0 && !invade, `陣地 ${baseCells[0]}/${baseCells[1]}マス・敵の侵入 ${invade ? "あり" : "なし"}（露見から12秒で自動帰還）`);
    add("mech", "絡繰変更", reachOK, `仕掛け扉 ${map.mechs.length}組・どの位相でも旗へ行ける（敷居に人がいる間は切替を延期＝ルール側）`);
    // 旗室
