    for (const it of m.items) if (!it.taken && it.kind === "key" && Math.hypot(p.x - it.x, p.y - it.y) < 0.8 && p.exposed <= 0) { it.taken = true; g.keys[p.team]++; emit(g, "key", it.x, it.y, { team: p.team, life: 1 }); logEvent(g, "key", { id: p.id, team: p.team }); }
