    for (let d = 0.25; d <= len + 1e-6; d += 0.25) { const nx = p.x + Math.cos(p.angle) * d, ny = p.y + Math.sin(p.angle) * d; if (SOLID[cellAt(nx, ny)] || !pathClear(p.x, p.y, nx, ny)) break; ex = nx; ey = ny; }
    return { x: ex, y: ey };
